import{_ as o,o as e,c as r,a2 as s}from"./chunks/framework.BWuWLRhz.js";const h=JSON.parse('{"title":"快速面板設定","description":"","frontmatter":{},"headers":[],"relativePath":"zh-TW/user-guide/settings/quick-panel.md","filePath":"zh-TW/user-guide/settings/quick-panel.md","lastUpdated":1787752921000}'),l={name:"zh-TW/user-guide/settings/quick-panel.md"};function n(a,t,i,g,d,c){return e(),r("div",null,[...t[0]||(t[0]=[s('<h1 id="快速面板設定" tabindex="-1">快速面板設定 <a class="header-anchor" href="#快速面板設定" aria-label="Permalink to &quot;快速面板設定&quot;">​</a></h1><p><strong>快速面板（Quick Panel）</strong> 是 Lertaro 專為高頻檔案取用、專案上下文管理與桌面拖曳互動打造的浮動工作區。它會在按下快速鍵時自動停靠在目前前景活動視窗的右下角，讓你無需離開目前工作視窗即可快速瀏覽、拖入或分發常用檔案。</p><h2 id="_1-核心機制與總開關" tabindex="-1">1. 核心機制與總開關 <a class="header-anchor" href="#_1-核心機制與總開關" aria-label="Permalink to &quot;1. 核心機制與總開關&quot;">​</a></h2><ul><li><strong>啟用快速面板</strong>：總開關，關閉後將不再監聽呼出快速鍵。</li><li><strong>喚起快速鍵</strong>：預設快速鍵為 <strong><code>Ctrl+F2</code></strong>（可在<a href="./hotkeys-page.html"><strong>設定 → 快速鍵</strong></a>中自訂）。</li><li><strong>智慧貼靠與尺寸條件約束</strong>：面板預設尺寸為宿主視窗寬高的各二分之一（最小尺寸限制為 <code>280 × 200px</code>，確保內容與篩選框完整可用）。若目前處於 Lertaro 自身視窗時按快速鍵會被安全忽略，防止視窗重疊；面板開啟狀態下再次按下同款快速鍵可一鍵關閉。</li><li><strong>快速跳轉聯動</strong>：面板開啟期間，目前選取分組所指向的實體目錄會被自動記錄為活動目錄。在任意系統檔案對話方塊中按下快速跳轉快速鍵（預設 <code>Ctrl+G</code>），即可直接跳轉到該目錄。</li></ul><h2 id="_2-工作區-workspaces" tabindex="-1">2. 工作區（Workspaces） <a class="header-anchor" href="#_2-工作區-workspaces" aria-label="Permalink to &quot;2. 工作區（Workspaces）&quot;">​</a></h2><p>工作區用於按專案或任務組織一組相關的資料夾來源：</p><ul><li><strong>工作區清單管理</strong>：左側清單呈現已建立的工作區，支援<strong>新建工作區</strong>、<strong>複製工作區</strong>與<strong>刪除工作區</strong>，可透過拖曳左側手柄調整其在面板索引標籤列中的前後排列順序。</li><li><strong>工作區屬性</strong>： <ul><li><strong>名稱</strong>：索引標籤頁顯示的文字（留空時將自動使用跟隨系統語言的預設名稱）。</li><li><strong>啟用開關</strong>：勾選狀態決定是否在面板索引標籤列中顯示。在面板中按一下索引標籤上的 <strong>×</strong> 按鈕即是將該工作區臨時隱藏，可在此處重新勾選還原。</li></ul></li></ul><p>選取的工作區可透過右側的兩個子索引標籤進行精細化設定：<strong>來源</strong>與<strong>應用程式</strong>。</p><h2 id="_3-來源設定-sources" tabindex="-1">3. 來源設定（Sources） <a class="header-anchor" href="#_3-來源設定-sources" aria-label="Permalink to &quot;3. 來源設定（Sources）&quot;">​</a></h2><p>每個來源代表工作區內部的一個獨立內容分組：</p><ul><li><strong>新增資料夾</strong>：按一下<strong>新增資料夾</strong>按鈕選取實體目錄。</li><li><strong>顯示模式（Display Mode）</strong>： <ul><li><strong>最近改動的檔案</strong> —— 由記憶體索引毫秒級直接應答，僅展示近期發生變動的檔案（最新排在最前）。</li><li><strong>全部內容，最新在前</strong> —— 呈現全部檔案，按修改時間降序排列。</li><li><strong>全部內容，按名稱</strong> —— 適合作為固定檔案的快捷工具列。</li></ul></li><li><strong>包含子資料夾</strong>：開啟後將遞迴收錄其所有子目錄下的檔案。</li><li><strong>接受拖入的檔案</strong>：開啟後，支援直接從外部將檔案、資料夾或瀏覽器圖片拖入該分組，Lertaro 會自動呼叫 Windows 原生複製介面將檔案複製進該目錄（具備衝突提示與復原支援）。</li><li><strong>檔案過濾規則</strong>：可使用萬用字元或搜尋語法中的 <code>@</code> 篩選器限制該分組展示的檔案類型（例如 <code>*.mp4;*.mkv</code>、<code>*.lnk;:@doc;:@img</code> 或 <code>*.lnk;:@doc|img</code>）。</li><li><strong>最大條數與時間限制</strong>：可限制最大展示數量（設為 0 表示不限制）及僅展示若干分鐘內改動過的檔案。</li><li><strong>詳細清單 vs 縮圖平鋪</strong>：支援按分組獨立選擇以清單形式還是縮圖網格平鋪展示（平鋪時自動等比拉伸並保持畫面原始比例）。</li></ul><h2 id="_4-外掛模組索引標籤-plugin-tabs" tabindex="-1">4. 外掛模組索引標籤（Plugin Tabs） <a class="header-anchor" href="#_4-外掛模組索引標籤-plugin-tabs" aria-label="Permalink to &quot;4. 外掛模組索引標籤（Plugin Tabs）&quot;">​</a></h2><p>除自訂工作區外，外掛模組亦可直接向快速面板註冊全域動態清單。CoreExtensions 核心外掛模組內建了五個實用索引標籤：</p><table tabindex="0"><thead><tr><th style="text-align:left;">外掛模組索引標籤</th><th style="text-align:left;">內容說明</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>我的最愛</strong></td><td style="text-align:left;">集中展示你的星標收藏項目，網址點擊後在瀏覽器中開啟。</td></tr><tr><td style="text-align:left;"><strong>搜尋歷程記錄</strong></td><td style="text-align:left;">展示你透過 Lertaro 開啟過的最近項目與應用程式。</td></tr><tr><td style="text-align:left;"><strong>Windows 歷程記錄</strong></td><td style="text-align:left;">自動解析 Windows 系統級的「最近使用的文件」並列出真實實體檔案。</td></tr><tr><td style="text-align:left;"><strong>上次目錄</strong></td><td style="text-align:left;">自動追蹤並遞回你在檔案總管或檔案對話方塊中剛剛離開的目錄。</td></tr><tr><td style="text-align:left;"><strong>最近檔案</strong></td><td style="text-align:left;">由背景記憶體索引直接彙總呈現所有設定目錄下的最新變動檔案。</td></tr></tbody></table><p>可在清單右側獨立控制此類外掛模組索引標籤的顯示狀態以及採用平鋪還是清單檢視。</p><h2 id="_5-應用程式綁定與獨立黑名單" tabindex="-1">5. 應用程式綁定與獨立黑名單 <a class="header-anchor" href="#_5-應用程式綁定與獨立黑名單" aria-label="Permalink to &quot;5. 應用程式綁定與獨立黑名單&quot;">​</a></h2><ul><li><strong>應用程式關聯（Applications）</strong>：可為工作區指定一個或多個前景處理程序名稱（如 <code>chrome.exe</code> 或 <code>devenv.exe</code>）。當你在該軟體上呼出快速面板時，面板將自動直達該關聯工作區，免去手動切換索引標籤的麻煩。</li><li><strong>僅快速面板黑名單</strong>：可在此設定不希望被快速面板打擾的處理程序名單。該名單會<strong>疊加</strong>在全域快速鍵黑名單之上，專用於處理不希望被面板遮擋但無需全域停用的特殊程式。</li></ul><h2 id="_6-面板互動指南" tabindex="-1">6. 面板互動指南 <a class="header-anchor" href="#_6-面板互動指南" aria-label="Permalink to &quot;6. 面板互動指南&quot;">​</a></h2><ul><li><strong>即時模糊過濾</strong>：面板右上角內建搜尋過濾框，支援 fzf 模糊比對與拼音別名，輸入即可即時篩選目前工作區。</li><li><strong>全鍵盤流暢導覽</strong>：使用上下方向鍵可無縫跨越不同分組連續捲動；在選取的項目上按下 <code>Enter</code> 鍵即可直接開啟。</li><li><strong>索引標籤快捷切換</strong>：按住 <code>Ctrl</code> + <code>1</code>–<code>9</code> 即可在各個工作區與外掛模組索引標籤間快速跳轉。</li><li><strong>QuickLook 預覽與釘住</strong>：選取項目後按 <code>Alt+P</code> 可在面板側邊呼出即時預覽；按 <code>Ctrl+T</code> 可釘住面板使其在失去焦點時不自動消失。</li></ul>',19)])])}const p=o(l,[["render",n]]);export{h as __pageData,p as default};
